import { AS_OF, disclosed, formatDate, inWindow, money, windows } from "@/components/deals/deals";
import { crossTab, deriveRecords, groupBy } from "@/components/patent-analyser/analysis";
import { workedExample } from "@/components/patent-analyser/sheet";
import type { Paper, Patent, Product } from "@/data/competitors";
import type { Deal } from "@/data/deals";
import type { Article } from "@/data/news";
import type { Active } from "@/data/regulatory";

// Deliverables are assembled from data the other modules already hold (passed
// in from the API layer). Nothing here is generated by a model, so every point
// is "retrieved".

export type Page = { title: string; points: string[]; sources: string[] };

export type TemplateId = "patent-landscape" | "paper-digest" | "teardown" | "quarterly-deck";

// Everything the templates read, fetched once by the Deliverables page.
export type SourceData = {
  patents: Patent[];
  papers: Paper[];
  products: Product[];
  actives: Active[];
  articles: Article[];
  deals: Deal[];
};

export const EMPTY_SOURCE_DATA: SourceData = {
  patents: [],
  papers: [],
  products: [],
  actives: [],
  articles: [],
  deals: [],
};

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

const patentSet = deriveRecords(workedExample, []);
const SHEET_SOURCE = `Patent Sheet Analyser · ${workedExample.name} (${workedExample.rows.length} records)`;
const productSource = (products: Product[]) => `Product Library (${products.length} SKUs)`;
const ACTIVES_SOURCE = "Regulatory & Actives · Actives Watch";

function patentLandscape(): Page[] {
  const recs = patentSet.records;
  const filers = groupBy(recs, "Filer");
  const years = groupBy(recs, "Priority year").filter((g) => g.value !== "Unknown");
  const places = groupBy(recs, "Jurisdiction");
  const techs = groupBy(recs, "Technology");
  const peak = years.slice().sort((a, b) => b.records.length - a.records.length)[0];
  const tab = crossTab(recs, "Filer", "Technology");
  const gaps = tab.rows.flatMap((row, r) =>
    tab.cols.filter((_, c) => tab.cells[r][c].length === 0).map((col) => `${row} × ${col}`),
  );

  return [
    {
      title: "Cover & executive summary",
      points: [
        `${plural(recs.length, "patent record")} from ${plural(filers.length, "filer")} across ${plural(places.length, "jurisdiction")}, ${years[0]?.value}–${years[years.length - 1]?.value}.`,
        `Most active filer: ${filers[0].value} with ${filers[0].records.length} filings.`,
        `Leading jurisdiction: ${places[0].value} (${Math.round((places[0].records.length / recs.length) * 100)}% of filings).`,
      ],
      sources: [SHEET_SOURCE],
    },
    {
      title: "Filing trends by year",
      points: [
        ...years.map((y) => `${y.value}: ${plural(y.records.length, "filing")}`),
        peak ? `Peak year: ${peak.value}.` : "",
      ].filter(Boolean),
      sources: [SHEET_SOURCE],
    },
    {
      title: "Top assignees",
      points: filers.slice(0, 5).map((f, i) => `${i + 1}. ${f.value} — ${plural(f.records.length, "filing")}`),
      sources: [SHEET_SOURCE],
    },
    {
      title: "Technology clusters",
      points: techs.slice(0, 5).map((t) => `${t.value}: ${plural(t.records.length, "filing")}`),
      sources: [SHEET_SOURCE],
    },
    {
      title: "Geographic coverage",
      points: places.map((p) => `${p.value}: ${plural(p.records.length, "filing")}`),
      sources: [SHEET_SOURCE],
    },
    {
      title: "White-space opportunities",
      points: gaps.length
        ? [
            `${gaps.length} of ${tab.rows.length * tab.cols.length} filer–technology combinations have no filings.`,
            ...gaps.slice(0, 4).map((g) => `Open: ${g}`),
          ]
        : ["Every filer–technology combination has at least one filing."],
      sources: [SHEET_SOURCE],
    },
  ];
}

function paperDigest(data: SourceData = EMPTY_SOURCE_DATA): Page[] {
  const { papers } = data;
  const avg = papers.length ? Math.round(papers.reduce((s, p) => s + p.confidence, 0) / papers.length) : 0;
  const journals = papers.map((p) => `${p.journal} (${p.year})`);
  return [
    {
      title: "Cover & key takeaways",
      points: papers.length
        ? [
            `${plural(papers.length, "paper")} reviewed across ${plural(new Set(papers.map((p) => p.theme)).size, "theme")}; average source confidence ${avg}%.`,
            ...papers.map((p) => p.insight),
          ]
        : ["No papers are available in the current source set."],
      sources: journals,
    },
    {
      title: "Paper-by-paper summaries",
      points: papers.length ? papers.map((p) => `${p.title} (${p.journal}, ${p.year}): ${p.summary}`) : ["No paper summaries available."],
      sources: journals,
    },
    {
      title: "Emerging themes",
      points: papers.length ? papers.map((p) => `${p.theme}: ${p.insight}`) : ["No emerging themes available."],
      sources: journals,
    },
  ];
}

function claimCounts(products: Product[]) {
  const counts = new Map<string, number>();
  for (const p of products) for (const c of p.claims) counts.set(c, (counts.get(c) ?? 0) + 1);
  return [...counts].sort((a, b) => b[1] - a[1]);
}

function teardown(data: SourceData = EMPTY_SOURCE_DATA): Page[] {
  const { products } = data;
  const prices = products.map((p) => p.price);
  const byPrice = products.slice().sort((a, b) => a.price - b.price);
  const priceRange = prices.length ? `Shelf prices range ₹${Math.min(...prices)}–₹${Math.max(...prices)}.` : "No shelf prices are available yet.";
  return [
    {
      title: "Cover & product overview",
      points: products.length
        ? [
            `${plural(products.length, "SKU")} from ${[...new Set(products.map((p) => p.brand))].join(", ")}.`,
            priceRange,
          ]
        : ["No SKUs are available in the current source set."],
      sources: [productSource(products)],
    },
    {
      title: "Actives & formulation",
      points: products.length ? products.map((p) => `${p.brand} ${p.name}: ${p.active}, ${p.format}`) : ["No active/formulation data available."],
      sources: [productSource(products), ACTIVES_SOURCE],
    },
    {
      title: "Format & packaging claims",
      points: products.length
        ? claimCounts(products)
            .slice(0, 6)
            .map(([claim, n]) => `“${claim}” on ${plural(n, "SKU")}`)
        : ["No packaging claims available."],
      sources: [productSource(products)],
    },
    {
      title: "Price positioning",
      points: products.length ? byPrice.map((p) => `₹${p.price} — ${p.brand} ${p.name} (${p.format})`) : ["No pricing data available."],
      sources: [productSource(products)],
    },
  ];
}

function quarterlyDeck(data: SourceData = EMPTY_SOURCE_DATA): Page[] {
  const { patents, products, actives, articles, deals } = data;
  const quarter = deals.filter((d) => inWindow(d, windows("90D").current));
  const largest = quarter.slice().sort((a, b) => (b.amount ?? 0) - (a.amount ?? 0)).slice(0, 3);
  const regulatoryNews = articles.filter((a) => a.category === "Regulatory");
  const productNews = articles.filter((a) => a.category === "Product" || a.category === "Industry");
  const companyNews = articles.filter((a) => a.category === "People & Company");
  const flagged = actives.filter((a) => a.status !== "Approved");
  const cliffs = actives
    .filter((a) => /^\d{4}$/.test(a.patentCliff))
    .sort((a, b) => Number(a.patentCliff) - Number(b.patentCliff));
  const filers = groupBy(patentSet.records, "Filer");
  const dealSources = [...new Set(quarter.map((d) => d.source))];
  const pages: Page[] = [
    {
      title: "Cover",
      points: [`Quarterly landscape review · as of ${formatDate(AS_OF)}`, "Patents · competitors · deals · regulatory · claims"],
      sources: [],
    },
    {
      title: "Quarter at a glance",
      points: [
        `${plural(quarter.length, "deal")} worth ${money(disclosed(quarter))} in the last 90 days.`,
        `${plural(patents.length, "strategic filing")} tracked; ${patents.filter((p) => p.status === "Pending").length} still pending.`,
        `${plural(flagged.length, "active")} not fully approved: ${flagged.map((a) => `${a.name} (${a.status})`).join(", ")}.`,
        `${plural(articles.length, "news item")} monitored.`,
      ],
      sources: ["Deals & Investments", "Competitor Intelligence · Strategic filings", ACTIVES_SOURCE, "News"],
    },
    {
      title: "Patent filings",
      points: patents.map((p) => `${p.number} — ${p.assignee}, ${p.active} (${p.technology}), ${p.status.toLowerCase()}`),
      sources: ["Competitor Intelligence · Patent Landscaping"],
    },
    {
      title: "Patent landscape map",
      points: filers.slice(0, 5).map((f) => `${f.value}: ${plural(f.records.length, "filing")}`),
      sources: [SHEET_SOURCE],
    },
    {
      title: "Competitor launches",
      points: productNews.slice(0, 4).map((a) => `${a.title} (${a.source}, ${a.time})`),
      sources: productNews.slice(0, 4).map((a) => a.source),
    },
    {
      title: "Competitor momentum",
      points: companyNews.length
        ? companyNews.map((a) => `${a.title} — ${a.summary}`)
        : ["No company moves tracked this quarter."],
      sources: companyNews.map((a) => a.source),
    },
    {
      title: "Deals & investments",
      points: largest.map((d) => `${d.headline} (${formatDate(d.date)})`),
      sources: dealSources,
    },
    {
      title: "Regulatory changes",
      points: regulatoryNews.length
        ? regulatoryNews.map((a) => `${a.title} — ${a.summary}`)
        : ["No regulatory news this quarter."],
      sources: regulatoryNews.map((a) => a.source),
    },
    {
      title: "Registration status",
      points: actives.map((a) => `${a.name}: ${a.status} in ${a.markets}; risk ${a.risk.toLowerCase()}`),
      sources: [ACTIVES_SOURCE],
    },
    {
      title: "Claims watch",
      points: claimCounts(products)
        .slice(0, 5)
        .map(([claim, n]) => `“${claim}” used on ${plural(n, "competitor SKU")}`),
      sources: [productSource(products)],
    },
    {
      title: "Outlook",
      points: cliffs.slice(0, 4).map((a) => `${a.name} patent cliff ${a.patentCliff} — plan formulations before it opens.`),
      sources: [ACTIVES_SOURCE],
    },
  ];
  return [
    ...pages,
    {
      title: "Appendix & sources",
      points: [...new Set(pages.flatMap((p) => p.sources))].map((s, i) => `[${i + 1}] ${s}`),
      sources: [],
    },
  ];
}

export const builders: Record<TemplateId, (data?: SourceData) => Page[]> = {
  "patent-landscape": patentLandscape,
  "paper-digest": paperDigest,
  teardown,
  "quarterly-deck": quarterlyDeck,
};

export function toMarkdown(title: string, pages: Page[]) {
  return [
    `# ${title}`,
    `_Assembled ${formatDate(AS_OF)} from Entopedia module data._`,
    ...pages.map((p, i) =>
      [
        `## ${i + 1}. ${p.title}`,
        ...p.points.map((pt) => `- ${pt}`),
        p.sources.length ? `\nSources: ${p.sources.join("; ")}` : "",
      ].join("\n"),
    ),
  ].join("\n\n");
}
